import json
import xml.etree.ElementTree as E
s=json.load(open('source.json')); p=json.load(open('answer.json'))
def compact(x):
 r=E.fromstring('<root>'+x+'</root>')
 def clean(n):
  if n.tag=='table':
   return '\\n[TABLE]\\n'+'\\n'.join(' | '.join(' '.join(' '.join(c.itertext()).split()) for c in row) for row in n.findall('.//tr'))+'\\n[/TABLE]\\n'
  if n.tag=='br': return '\\n'
  return (n.text or '')+''.join(clean(c)+(c.tail or '') for c in n)
 return clean(r).strip()
for i in range(2):
 print('\\nARTICLE',s[i]['number'],'SOURCE:')
 print(compact(s[i]['source_xml']))
 print('NOTES SOURCE:',s[i]['source_notes_xml'])
 print('PROPOSITION:')
 print(compact(p[i]['proposed_xml']))
PY"

